-- Career completeness, part 2c: Media, Medical, Research, Technology, and the remaining
-- official careers whose descriptions were too short. Same columns as part 2a.

update public.careers c set
  description = coalesce(v.descr, c.description),
  path_steps = string_to_array(v.steps, ' | '),
  top_employers = string_to_array(v.emp, ' | '),
  related_college_slugs = case when v.cols is null then c.related_college_slugs else string_to_array(v.cols, ' ') end
from (values
  -- Media
  ('content-creator', 'Makes videos, posts, podcasts or articles for platforms such as YouTube, Instagram and blogs, builds an audience around a topic, and earns through ads, brand deals and subscriptions. Needs consistency, creativity and an understanding of what the audience wants.',
   'Pick a topic you know and enjoy | Learn shooting, editing (Premiere Pro, CapCut) and writing for the web | Post regularly and study your analytics | Build a community and collaborate with other creators | Earn through ads, brand deals and memberships | Grow into a full-time creator or a content agency',
   'Self-employed (YouTube, Instagram, podcasts) | Digital media companies | Brands'' content teams | Creator agencies', null),
  ('film-director', 'Turns a script into a film, series or advertisement: guides actors, decides how each scene is shot, and works with the cinematographer, editor and producer to create the final work.',
   'Class 12 in any stream | Graduate in film, mass communication or any subject | Join FTII / SRFTI (through JET) or a film school, or learn by assisting directors | Make short films and enter festivals | Work as an assistant director on sets | Direct ads, web series or your first feature',
   'Film production houses (Yash Raj, Dharma) | OTT platforms (Netflix, Amazon Prime) | Advertising production houses | Television channels | Independent films', 'ftii-pune srfti-kolkata nsd-delhi ajkmcrc-delhi'),
  ('journalist', 'Finds, checks and reports news for newspapers, TV, radio and digital media. Interviews people, investigates stories and writes or presents them clearly and fairly.',
   'Class 12 in any stream | BA Journalism and Mass Communication (CUET UG or college entrances) or any graduation | PG Diploma from IIMC, ACJ or XIC (through their entrances) | Internships with newspapers, TV channels or news websites | Start as a reporter or sub-editor | Grow to correspondent, editor or anchor',
   'The Hindu | Indian Express | Times of India | NDTV | India Today | ANI and PTI | Digital news outlets', 'iimc-delhi acj-chennai ajkmcrc-delhi simc-pune xic-mumbai mic-manipal'),
  ('performing-artist', null,
   'Start training early in a classical dance, music or theatre form under a guru or institute | Class 12, then BPA / MPA from a performing arts university, or NSD for theatre | Perform at competitions, festivals and sabhas | Get graded by Doordarshan / AIR or empanelled with ICCR | Build a following through performances and online | Perform, teach or work in film and television',
   'Cultural institutions (Sangeet Natak Akademi, ICCR) | Theatre companies | Film and television | Dance and music schools | Self-employed performance and teaching', 'nsd-delhi kalakshetra-chennai iksv-khairagarh rbu-kolkata msu-finearts-baroda ftii-pune'),
  ('sound-designer', 'Records, designs and mixes the sound in films, series, games and music: dialogue, sound effects, background score and the final mix that makes a scene feel real.',
   'Class 12 in any stream (Physics helps) | Learn audio software (Pro Tools, Logic, Ableton) and recording basics | Join FTII / SRFTI sound recording and design through JET, or a sound engineering course | Assist in a recording or post-production studio | Build a portfolio of film, game or music sound | Work as a sound designer, recordist or mixing engineer',
   'Film and OTT production houses | Recording and post-production studios | Game studios | Advertising production houses', 'ftii-pune srfti-kolkata'),

  -- Medical
  ('dentist', 'Diagnoses and treats problems of the teeth, gums and mouth: fillings, root canals, extractions, braces and dentures, and teaches patients to care for their teeth. Dentists work in hospitals, clinics or their own practice.',
   'Class 12 with Physics, Chemistry and Biology (at least 50%) | Clear NEET UG | BDS (4 years plus 1 year internship) | Register with the State Dental Council | Practise in a hospital or clinic, or start your own | Optional: MDS (through NEET MDS) to specialise in orthodontics, oral surgery and other fields',
   'Government hospitals and dental colleges | Clove Dental and other chains | Private clinics | Own practice | Armed Forces Dental Corps', 'maulana-azad-institute-dental-sciences kgmu-lucknow bhu-ims manipal-university amrita-university srmc-chennai'),
  ('doctor-mbbs', 'Diagnoses and treats illness and injury, prescribes medicines, and guides patients on health. An MBBS doctor can work as a general physician or go on to specialise (MD / MS) in fields such as medicine, surgery or paediatrics.',
   null, 'Government hospitals (AIIMS, state medical colleges) | Private hospitals (Apollo, Fortis, Max) | Primary health centres | Armed Forces Medical Services | Own clinic', null),
  ('nursing', 'Cares for patients day and night: gives medicines and injections, monitors their condition, assists doctors and supports patients and families. Nurses work in hospitals, community health and abroad, where Indian nurses are in demand.',
   null, 'Government hospitals (AIIMS) | Private hospitals | Military Nursing Service | Community health centres | Hospitals abroad', null),
  ('pharmacist', 'Prepares and dispenses medicines, checks prescriptions for safety, and advises patients on how to take them. Pharmacists also work in drug manufacturing, research, quality control and regulatory affairs.',
   null, 'Hospital pharmacies | Retail chains (Apollo Pharmacy, MedPlus) | Pharma companies (Sun Pharma, Cipla, Dr. Reddy''s) | Drug control departments', null),
  ('physiotherapist', 'Helps people recover movement and strength after injury, surgery, stroke or illness using exercises, manual therapy and equipment. Works with athletes, older people, children and patients in hospitals and clinics.',
   'Class 12 with Physics, Chemistry and Biology | Bachelor of Physiotherapy (BPT, 4.5 years including internship) through NEET UG or state / university entrances | Internship in a hospital | Register with your state physiotherapy council | Work in a hospital, sports team or clinic | Optional: MPT to specialise in sports, neuro or orthopaedic physiotherapy',
   'Hospitals (AIIMS, Apollo, Fortis) | Sports teams and academies | Rehabilitation centres | Own clinic | Home care services', 'jmi-delhi manipal-university srmc-chennai amrita-university'),
  ('psychologist', 'Studies how people think, feel and behave, and helps them with stress, anxiety, relationships and other problems through counselling and assessment. Clinical work needs further RCI-recognised training.',
   'Class 12 in any stream | B.A. / B.Sc Psychology through CUET UG or university entrances | M.A. / M.Sc Psychology | Supervised practice (internships in hospitals, schools, NGOs) | For clinical practice: M.Phil / Professional Diploma recognised by RCI | Work as a counsellor, in HR, in research, or in clinical settings',
   'Hospitals and clinics | Schools and colleges | Corporate HR and wellness teams | NGOs | Online counselling platforms | Own practice', 'university-of-delhi lsr-delhi christ-university amity-psychology-noida jmi-delhi nimhans-bangalore jain-university-bangalore'),
  ('clinical-psychologist', null, null,
   'NIMHANS and psychiatric hospitals | General hospitals | Rehabilitation centres | Schools and universities | Own practice', 'nimhans-bangalore amity-psychology-noida christ-university university-of-delhi jmi-delhi'),
  ('dietitian-nutritionist', null, null,
   'Hospitals (AIIMS, Apollo, Fortis) | Fitness and wellness centres | Food companies | Government nutrition programmes (ICDS, POSHAN) | Own practice', 'manipal-university amity-university srmc-chennai'),
  ('forensic-scientist', null,
   'Class 12 with science (Physics, Chemistry and Biology or Mathematics) | B.Sc Forensic Science, or B.Sc in Chemistry, Biology or Physics | M.Sc Forensic Science (through CUET PG or a university entrance) | Lab training in toxicology, DNA, ballistics or documents | Apply for Scientific Officer / Assistant posts in state or central forensic labs (state PSC or UPSC / SSC recruitment) | Grow to senior scientific officer or lab head',
   'Central and State Forensic Science Laboratories | CBI and NIA | Police departments | Private forensic and cyber-forensic labs', 'amity-university lpu chandigarh-university university-of-delhi'),
  ('investment-adviser', null,
   'Graduation in any field (commerce, economics or finance help) | Pass the NISM Series X-A and X-B Investment Adviser certifications | Gain the experience SEBI requires, or a relevant postgraduate qualification | Register with SEBI as an Investment Adviser (individual or firm) | Charge clients a fee for advice (not commissions) and follow SEBI''s conduct rules | Build a client base over time',
   'Registered investment advisory firms | Wealth management firms | Banks'' advisory desks | Own SEBI-registered practice', null),
  ('cinematographer', null,
   'Class 12 in any stream | Learn photography and camera basics | Join FTII / SRFTI cinematography through JET, or a film school | Assist a director of photography on ads, music videos and films | Shoot short films to build a showreel | Work as a cinematographer (DoP) on ads, series and features',
   'Film production houses | OTT platforms | Advertising production houses | Television channels | Freelance', 'ftii-pune srfti-kolkata'),
  ('film-editor', null,
   'Class 12 in any stream | Learn editing software (Adobe Premiere Pro, DaVinci Resolve, Avid) | Join FTII / SRFTI editing through JET, or a film school | Assist an editor in a post-production studio | Edit short films, ads and YouTube content for a showreel | Work as an editor on films, series and ads',
   'Post-production studios | Film and OTT production houses | Advertising agencies | News and digital media | Freelance', 'ftii-pune srfti-kolkata'),
  ('veterinary-doctor', 'Treats sick and injured animals, from pets to cattle and wildlife, performs surgery and vaccinations, and protects public health from animal diseases. Works in government veterinary hospitals, dairy and poultry farms, and private clinics.',
   'Class 12 with Physics, Chemistry and Biology | Clear NEET UG (15% seats through VCI counselling, the rest through state counselling) | B.V.Sc and A.H. (5 years plus a 1-year internship) | Register with the Veterinary Council of India or your State Veterinary Council | Join a state animal husbandry department, dairy or poultry company, or start a clinic | Optional: M.V.Sc to specialise',
   'State Animal Husbandry Departments | Government veterinary hospitals | Dairy cooperatives (Amul) | Poultry and pharma companies | Wildlife and zoos | Own clinic', 'ivri-bareilly mafsu-nagpur rajuvas-bikaner'),

  -- Research
  ('academic-researcher', 'Asks new questions in a subject and answers them through experiments, data or theory, publishes the results in journals, and often teaches and guides students at a university or research institute.',
   'Bachelor''s degree in your subject (B.Sc, B.Tech, B.A.) | Master''s degree (through JAM, CUET PG or institute entrances) | Clear a fellowship exam (CSIR NET-JRF, UGC NET-JRF, GATE, JEST, TIFR GS) | PhD (4-5 years) with research papers | Postdoctoral research in India or abroad | Faculty or scientist position',
   'Universities | IITs, IISERs and IISc | CSIR, ICMR and DST laboratories | TIFR and other research institutes | Industry R&D labs', null),
  ('agricultural-scientist', 'Researches better crops, seeds, soil health, pest control and animal husbandry to raise farm output and incomes. Works at ICAR institutes, agricultural universities and agri-companies.',
   'Class 12 with Biology (or PCM for agricultural engineering) | B.Sc (Hons) Agriculture through ICAR AIEEA or state university entrances | M.Sc through ICAR AIEEA-PG | ICAR JRF / SRF fellowship and PhD | Clear ICAR ASRB (ARS) exam for scientist posts | Research at an ICAR institute or university',
   'ICAR institutes (IARI and others) | State Agricultural Universities | Seed and agritech companies | International centres (ICRISAT, IRRI)', null),
  ('archaeologist', 'Discovers and studies the human past through excavation, monuments, inscriptions and artefacts, and helps protect India''s heritage sites.',
   'Class 12 (Humanities helps) | B.A. History or Ancient Indian History and Culture | M.A. Archaeology or Ancient History | Excavation training and fieldwork | PG Diploma in Archaeology from the Institute of Archaeology (ASI) or UGC NET | Join ASI, a state archaeology department, museum or university',
   'Archaeological Survey of India | State archaeology departments | Museums (National Museum) | INTACH | Universities', 'bhu university-of-delhi amu calcutta-university madras-university'),
  ('biotech-researcher', 'Uses living cells, genes and proteins to develop medicines, vaccines, diagnostics, better crops and industrial enzymes, working in labs at institutes and biotech companies.',
   'Class 12 with Biology (PCB or PCMB) | B.Sc / B.Tech Biotechnology | M.Sc / M.Tech Biotechnology (through JAM, GATE or university entrances) | Clear DBT-JRF or CSIR NET-JRF for a funded PhD | PhD and research publications | Scientist roles in institutes or industry R&D',
   'Biocon | Serum Institute | Bharat Biotech | DBT institutes (NII, NCBS) | CSIR labs | Diagnostic companies', 'iisc-bangalore ncbs-bangalore iit-delhi iit-bombay jnu iiser-pune'),
  ('clinical-researcher', 'Plans and runs clinical trials that test new medicines and treatments on volunteers, making sure studies are ethical, safe and follow ICMR and CDSCO rules.',
   'Class 12 with Biology | B.Pharm, B.Sc Life Sciences, Nursing or MBBS | M.Pharm, M.Sc or a PG diploma in Clinical Research (NIPER JEE for NIPERs) | Learn Good Clinical Practice (GCP) guidelines | Join as a clinical research coordinator or associate | Grow to clinical trial manager or medical affairs',
   'Contract research organisations (IQVIA, Parexel) | Pharma companies | Hospitals | ICMR | CDSCO', null),
  ('environmental-scientist', 'Studies pollution, climate, water, forests and biodiversity, measures environmental damage, and finds solutions. Works in pollution control boards, research institutes, consultancies and NGOs.',
   'Class 12 with science | B.Sc in Environmental Science, Chemistry, Biology or B.Tech | M.Sc Environmental Science (or M.Tech through GATE) | Fieldwork and lab training | Join a pollution control board, consultancy or research institute (UGC NET / CSIR NET for research) | Specialise in climate, water, waste or impact assessment',
   'Central and State Pollution Control Boards | Environmental consultancies | TERI and CSE | Ministry of Environment | Companies'' sustainability teams', null),
  ('linguist', 'Studies how languages work: sounds, grammar, meaning and how languages change. Works in teaching, translation, language technology (speech and text AI), dictionaries and documenting endangered languages.',
   'Class 12 in any stream | B.A. in a language or Linguistics | M.A. Linguistics | Clear UGC NET for teaching and a funded PhD | Learn computational tools if interested in language technology | Work in universities, language-tech companies, publishing or translation',
   'Universities | Central Institute of Indian Languages | Language technology companies (Google, Microsoft) | Translation agencies | Publishers', 'jnu university-of-delhi university-of-hyderabad bhu amu'),
  ('nanotech-researcher', 'Designs and studies materials and devices at the scale of atoms and molecules, used in electronics, medicine, energy and coatings.',
   'Class 12 with PCM | B.Tech or B.Sc in Physics, Chemistry, Materials or Electronics | M.Tech / M.Sc in Nanotechnology or Materials Science (GATE or JAM) | Clear CSIR NET or GATE for a funded PhD | PhD research on nanomaterials | Scientist roles in institutes or industry',
   'IISc and IITs | CSIR labs | JNCASR | Semiconductor and materials companies | DRDO labs', null),
  ('research-scientist', 'Does original scientific research in physics, chemistry, biology, mathematics or engineering, designing experiments, analysing data and publishing new findings at institutes, labs or companies.',
   'Class 12 with science (Olympiads and INSPIRE help) | B.Sc / BS-MS (IISER, IISc, NISER) or B.Tech | M.Sc through JAM, or integrated programmes | Clear CSIR NET-JRF, GATE, JEST or TIFR GS for a funded PhD | PhD and postdoctoral research | Scientist post at a research institute or industry lab',
   'TIFR | IISc | IISERs | CSIR laboratories | ISRO and DRDO | Industry R&D (Tata, Reliance)', null),
  ('space-scientist', 'Researches and builds technology for space: satellites, launch vehicles, remote sensing and space science missions. Most in India work at ISRO centres.',
   null, 'ISRO (VSSC, URSC, SAC and other centres) | Physical Research Laboratory | IIST | Space startups (Skyroot, Agnikul)', null),

  -- Technology
  ('ai-ml-engineer', 'Builds systems that learn from data, such as recommendation engines, chatbots, image recognition and fraud detection, and puts machine learning models into real products.',
   'Class 12 with Mathematics | B.Tech in CSE, AI or a related branch (JEE Main, state CETs, UGEE) | Strong maths: linear algebra, probability and statistics | Learn Python, ML libraries (scikit-learn, PyTorch) and build projects | Internships and Kaggle competitions | Join as an ML engineer; an M.Tech or MS helps for research roles',
   'Google | Microsoft | Amazon | Flipkart | Fractal | AI startups | Research labs', null),
  ('blockchain-developer', 'Builds applications on blockchains: smart contracts, crypto wallets, payment systems and decentralised apps, with a focus on security.',
   'Class 12 with Mathematics | B.Tech CSE or BCA / B.Sc CS | Learn programming, cryptography basics and how blockchains work | Learn Solidity and build smart contracts on test networks | Contribute to open-source projects and hackathons | Join a Web3 company or a bank''s blockchain team',
   'Polygon | CoinDCX | WazirX | Infosys and TCS blockchain units | Fintech startups', null),
  ('cloud-architect', 'Designs how a company''s software runs on cloud platforms such as AWS, Azure and Google Cloud, choosing services for scale, security and cost.',
   'Class 12 with Mathematics | B.Tech CSE / IT or BCA | Start as a software, system or DevOps engineer | Learn networking, Linux and one cloud platform deeply | Earn certifications (AWS Solutions Architect, Azure Architect) | Move to cloud architect after 5-8 years of experience',
   'Amazon Web Services | Microsoft | Google Cloud | TCS | Infosys | Accenture | Large enterprises', null),
  ('cybersecurity-analyst', 'Protects computer systems and networks from hackers: monitors for attacks, finds weaknesses, responds to incidents and helps keep data safe.',
   'Class 12 with Mathematics | B.Tech CSE / IT or BCA / B.Sc CS | Learn networking, Linux and security basics | Practise ethical hacking on legal labs (TryHackMe, CTFs) | Certifications (CompTIA Security+, CEH, OSCP) | Join a security operations centre (SOC), then specialise',
   'CERT-In | Banks | TCS and Wipro security units | Quick Heal | Deloitte | Palo Alto Networks | Big tech companies', null),
  ('data-scientist', 'Finds patterns in data to answer business questions and predict outcomes, using statistics, programming and machine learning, and explains findings with clear charts and reports.',
   'Class 12 with Mathematics | B.Tech, B.Sc Statistics / Mathematics or BCA | Learn Python or R, SQL and statistics | Learn machine learning and data visualisation through projects | Internships or Kaggle competitions | Join as a data analyst or scientist; a master''s helps',
   'Google | Amazon | Flipkart | Mu Sigma | Fractal | Banks | Consulting firms', null),
  ('devops-engineer', 'Automates how software is built, tested and released, and keeps servers and cloud systems running reliably, using tools such as Git, Docker, Kubernetes and CI/CD pipelines.',
   'Class 12 with Mathematics | B.Tech CSE / IT or BCA | Learn Linux, networking and scripting (Bash, Python) | Learn Git, Docker, Kubernetes and a cloud platform | Build CI/CD pipelines in projects | Join as a DevOps or site reliability engineer',
   'Amazon | Microsoft | Flipkart | Razorpay | TCS | Infosys | SaaS startups', null),
  ('full-stack-developer', 'Builds complete web applications: the parts users see (frontend, such as React) and the servers and databases behind them (backend, such as Node.js), and deploys them.',
   'Class 12 (Mathematics helps) | B.Tech CSE, BCA or any degree with strong coding skills | Learn HTML, CSS, JavaScript, React and a backend (Node.js) | Learn databases and Git | Build and deploy real projects for your portfolio | Join as a developer through internships or placements',
   'Product companies (Zomato, Swiggy, Razorpay) | IT services (TCS, Infosys) | Startups | Freelance clients', null),
  ('game-developer', 'Designs and programs video games for mobile, PC and consoles: gameplay, graphics, physics and multiplayer, usually in engines such as Unity or Unreal.',
   'Class 12 with Mathematics | B.Tech CSE or a degree in game design | Learn C# (Unity) or C++ (Unreal) | Build and publish small games | Join game jams and build a portfolio | Join a game studio as a developer',
   'Ubisoft India | Rockstar India | Nazara | Dream11 | Zynga India | Indie studios', null),
  ('product-manager', null,
   'Graduation (engineering or design helps) | Work 2-3 years as an engineer, designer, analyst or in business | Learn product thinking, user research and data | Optional: MBA (CAT, GMAT) for a switch into product | Move into an associate / product manager role | Grow to senior product manager and head of product',
   'Google | Microsoft | Flipkart | Swiggy | Razorpay | CRED | SaaS startups', null),
  ('software-engineer', 'Designs, writes, tests and maintains software, from mobile apps and websites to large systems used by millions. One of the largest and best-paid careers in India.',
   'Class 12 with Mathematics | B.Tech CSE / IT through JEE Main, BITSAT or state CETs (BCA / B.Sc CS also work) | Learn data structures, algorithms and one language well | Build projects and practise coding problems | Internship and campus placement | Grow from software engineer to senior engineer and architect',
   'Google | Microsoft | Amazon | Flipkart | TCS | Infosys | Wipro | Startups', null),
  ('data-engineer', null,
   'Class 12 with Mathematics | B.Tech CSE / IT or BCA | Learn SQL, Python and databases | Learn big-data tools (Spark, Kafka, Airflow) and a cloud platform | Build data pipeline projects | Join as a data engineer, then senior or lead data engineer',
   'Amazon | Walmart Global Tech | Flipkart | Uber | Fractal | Consulting firms', null),

  -- Official careers with short descriptions
  ('architect', 'Designs buildings and the spaces around them, from homes to hospitals and city layouts, balancing safety, cost, beauty and the environment. Only those registered with the Council of Architecture may call themselves architects in India.',
   null, 'Architecture firms | CPWD and state PWDs | Real estate developers | Urban development authorities | Own practice', null),
  ('school-teacher', 'Teaches children at primary, middle or secondary level, plans lessons, assesses progress and supports each student''s growth. Government school jobs need a B.Ed / D.El.Ed and a teacher eligibility test (CTET or state TET).',
   'Graduation in your subject (for secondary teaching) or Class 12 (for primary, via D.El.Ed) | B.Ed (2 years) or an integrated B.A./B.Sc B.Ed | Clear CTET or your state TET | Apply through KVS, NVS, state teacher recruitment or private schools | Teach and grow to senior teacher, then head of department or principal',
   'Government schools | Kendriya Vidyalayas | Navodaya Vidyalayas | Private schools | Coaching institutes', 'rie-bhubaneswar university-of-delhi jmi-delhi bhu amu'),
  ('special-education-teacher', 'Teaches children with disabilities such as hearing or visual impairment, autism, learning disabilities and intellectual disability, adapting lessons to each child. Must be registered with the Rehabilitation Council of India (RCI).',
   null, 'Special schools | Inclusive mainstream schools | NGOs | National institutes for persons with disabilities', null),
  ('merchant-navy-officer', null,
   'Class 12 with Physics, Chemistry and Mathematics (usually 60%+, with English) | Clear IMU CET or a DG Shipping-approved institute''s entrance | B.Sc Nautical Science (for deck officers) or B.Tech Marine Engineering (for engineers) | Sea training as a cadet on a ship | Clear the DG Shipping Certificate of Competency exams | Join as Third Officer or Fourth Engineer, rise to Captain or Chief Engineer',
   'Shipping Corporation of India | Maersk | MSC | Anglo-Eastern | Wallem | Oil and gas tanker companies', null)
) as v(slug, descr, steps, emp, cols)
where c.slug = v.slug;
